/* calendar.js — 今週の開催ウィジェット(T6)
 * 依存: window.KG_CALENDAR(build.ps1 が data/calendar.json から生成し、このファイルの先頭に連結する)
 *       window.KG_DATA.racecourses(競馬場名)、window.KG_SITE.basePath(無くても動く)
 * スロット: <div data-calendar="weekly"></div>                       … 今週の開催 + 次のGI
 *           <div data-calendar="course" data-course-id="tokyo"></div> … その競馬場の次の開催(3件)+ 次のGI
 * 「今日」は JST(UTC+9)で判定する。静的サイトなので全件をクライアントで持ち、表示時に計算する。
 * 描画後に <div data-cta="inline" data-promo="prediction"> を置き、window.KG_CTA.render() を呼ぶ(v2: 予想サイト promo 専用。
 * promos[].id=prediction の url が空なら何も出ない = GATE-9 まで非表示)。
 */
(function () {
  'use strict';

  var DAY_MS = 86400000;
  var JST_OFFSET_MS = 9 * 60 * 60 * 1000;
  var WEEKDAYS = ['日', '月', '火', '水', '木', '金', '土'];
  var TENTATIVE_MARK = '認可前';
  var JRA_CALENDAR_URL = 'https://www.jra.go.jp/keiba/calendar/';
  var ESC_MAP = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

  function esc(s) {
    return String(s === undefined || s === null ? '' : s).replace(/[&<>"']/g, function (c) { return ESC_MAP[c]; });
  }
  function str(v) { return (v === undefined || v === null) ? '' : String(v).trim(); }
  function pad(n) { return (n < 10 ? '0' : '') + n; }

  // ---- 設定・データ(防御的に読む) ----
  function getCalendar() {
    var cal = (window.KG_CALENDAR && typeof window.KG_CALENDAR === 'object') ? window.KG_CALENDAR : {};
    return {
      updated: str(cal.updated),
      days: Array.isArray(cal.days) ? cal.days : [],
      g1: Array.isArray(cal.g1) ? cal.g1 : []
    };
  }
  function getBase() {
    if (window.KG && typeof window.KG.base === 'string') return window.KG.base;
    var site = window.KG_SITE;
    return (site && typeof site.basePath === 'string') ? site.basePath : '';
  }
  function getCourses() {
    var d = window.KG_DATA;
    return (d && Array.isArray(d.racecourses)) ? d.racecourses : [];
  }
  function courseName(id) {
    var list = getCourses();
    for (var i = 0; i < list.length; i++) {
      if (list[i].id === id) return str(list[i].name) || id;
    }
    return id;
  }
  function shortName(id) { return courseName(id).replace(/競馬場$/, ''); }
  function courseUrl(id) { return getBase() + '/courses/' + encodeURIComponent(id) + '/'; }
  function courseLink(id, full) {
    return '<a class="kg-calendar__course" href="' + esc(courseUrl(id)) + '">' + esc(full ? courseName(id) : shortName(id)) + '</a>';
  }

  // ---- 日付(JST。内部表現は「その日の UTC 0時」のミリ秒。日付文字列は YYYY-MM-DD) ----
  function todayKey() {
    var d = new Date(Date.now() + JST_OFFSET_MS);
    return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
  }
  function keyToMs(key) {
    var p = String(key).split('-');
    return Date.UTC(+p[0], +p[1] - 1, +p[2]);
  }
  function msToKey(ms) {
    var d = new Date(ms);
    return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
  }
  function isKey(key) { return /^\d{4}-\d{2}-\d{2}$/.test(String(key)); }
  function fmtDate(key) {
    var d = new Date(keyToMs(key));
    return (d.getUTCMonth() + 1) + '/' + d.getUTCDate() + '(' + WEEKDAYS[d.getUTCDay()] + ')';
  }
  function fmtDateLong(key) {
    var d = new Date(keyToMs(key));
    return d.getUTCFullYear() + '年' + (d.getUTCMonth() + 1) + '月' + d.getUTCDate() + '日(' + WEEKDAYS[d.getUTCDay()] + ')';
  }
  // 月曜始まりの週 [start, end](end = 日曜)
  function weekOf(key) {
    var ms = keyToMs(key);
    var dow = new Date(ms).getUTCDay();
    var start = ms - ((dow + 6) % 7) * DAY_MS;
    return { start: msToKey(start), end: msToKey(start + 6 * DAY_MS), nextMonday: msToKey(start + 7 * DAY_MS) };
  }

  function isTentative(row) { return !!(row && str(row.notes).indexOf(TENTATIVE_MARK) !== -1); }
  function splitG1(s) {
    return str(s).split(/[、,]/).map(function (x) { return x.trim(); }).filter(function (x) { return x; });
  }

  // 日付でグループ化(配列の出現順を保つ = JRA の東→西の並び)。date 昇順で返す
  function groupByDate(rows) {
    var map = {};
    var keys = [];
    for (var i = 0; i < rows.length; i++) {
      var r = rows[i];
      if (!r || !isKey(r.date) || !str(r.courseId)) continue;
      if (!map[r.date]) { map[r.date] = []; keys.push(r.date); }
      map[r.date].push(r);
    }
    keys.sort();
    return keys.map(function (k) { return { date: k, rows: map[k] }; });
  }

  // 今週(今日以降)の開催。無ければ今日以降で直近の開催日が属する週。
  // 週内(月〜日)に開催がある場合だけ、翌月曜(祝日開催)も同じ週末として含める(T4 申し送り)
  function pickWeek(days, today) {
    var sorted = days.filter(function (r) { return r && isKey(r.date); });
    var inRange = function (w) {
      var rows = sorted.filter(function (r) { return r.date >= today && r.date >= w.start && r.date <= w.end; });
      if (rows.length === 0) return rows;
      return rows.concat(sorted.filter(function (r) { return r.date === w.nextMonday; }));
    };
    var week = weekOf(today);
    var rows = inRange(week);
    var fallback = false;
    if (rows.length === 0) {
      var future = sorted.filter(function (r) { return r.date >= today; }).map(function (r) { return r.date; }).sort();
      if (future.length === 0) return { groups: [], fallback: true };
      week = weekOf(future[0]);
      rows = inRange(week);
      fallback = true;
    }
    return { groups: groupByDate(rows), fallback: fallback };
  }

  function nextG1(g1, today, courseId) {
    var list = g1.filter(function (g) {
      return g && isKey(g.date) && g.date >= today && str(g.name) && (!courseId || g.courseId === courseId);
    }).sort(function (a, b) { return a.date < b.date ? -1 : (a.date > b.date ? 1 : 0); });
    return list.length ? list[0] : null;
  }
  function findDay(days, date, courseId) {
    for (var i = 0; i < days.length; i++) {
      if (days[i] && days[i].date === date && days[i].courseId === courseId) return days[i];
    }
    return null;
  }

  // ---- HTML 片 ----
  function tentativeMark() { return ' <span class="kg-calendar__tentative">(予定)</span>'; }

  function renderDayItem(group, today) {
    var links = group.rows.map(function (r) { return courseLink(r.courseId, false); }).join('<span class="kg-calendar__sep">・</span>');
    var g1names = [];
    var tentative = false;
    group.rows.forEach(function (r) {
      splitG1(r.g1).forEach(function (n) { if (g1names.indexOf(n) === -1) g1names.push(n); });
      if (isTentative(r)) tentative = true;
    });
    var html = '<li class="kg-calendar__item">' +
      '<span class="kg-calendar__date">' + esc(fmtDate(group.date)) +
      (group.date === today ? ' <span class="kg-calendar__today">本日</span>' : '') + '</span>' +
      '<span class="kg-calendar__courses">' + links + '</span>';
    g1names.forEach(function (n) { html += '<span class="kg-calendar__g1">GI ' + esc(n) + '</span>'; });
    if (tentative) html += tentativeMark();
    return html + '</li>';
  }

  function renderNextG1(g, days, today, withCourse) {
    if (!g) return '';
    var day = findDay(days, g.date, g.courseId);
    var when = g.date === today ? '<b class="kg-calendar__today">本日</b>' : '<b>' + esc(fmtDate(g.date)) + '</b>';
    var html = '<p class="kg-calendar__next"><span class="kg-calendar__next-label">次のGI</span> ' + when +
      ' <span class="kg-calendar__race">' + esc(g.name) + '</span>';
    if (withCourse) html += ' ' + courseLink(g.courseId, true);
    if (isTentative(day)) html += tentativeMark();
    return html + '</p>';
  }

  function renderFooter(cal) {
    var html = '<p class="kg-calendar__source">出典: <a href="' + JRA_CALENDAR_URL + '" target="_blank" rel="noopener">JRA 開催日程</a>';
    if (cal.updated) html += '(' + esc(cal.updated) + ' 時点)';
    html += '。天候等により変更される場合があります。</p>';
    html += '<div data-cta="inline" data-promo="prediction"></div>';
    return html;
  }

  function renderWeekly(slot, cal, today) {
    var picked = pickWeek(cal.days, today);
    var html = '<div class="kg-calendar kg-calendar--weekly">';
    html += '<h2 class="kg-calendar__title">今週の開催</h2>';
    if (picked.groups.length === 0) {
      html += '<p class="kg-calendar__empty">次回の開催日程は JRA の発表後に掲載します。</p>';
    } else {
      if (picked.fallback) html += '<p class="kg-calendar__note">今週は開催がありません。次の開催日程です。</p>';
      html += '<ul class="kg-calendar__list">';
      picked.groups.forEach(function (g) { html += renderDayItem(g, today); });
      html += '</ul>';
    }
    var g = nextG1(cal.g1, today, '');
    if (g) html += renderNextG1(g, cal.days, today, true);
    html += renderFooter(cal);
    html += '</div>';
    slot.innerHTML = html;
  }

  // データ範囲内に次回開催が無い場合の文言。その競馬場の最後の開催日(今日より前)が分かれば添える
  // 例: 「2026年の開催は 9/6(日) で終了しました。次回の開催日程は JRA の発表後に掲載します。」
  function renderNoUpcoming(cal, today, courseId) {
    var html = '<p class="kg-calendar__empty">';
    var last = lastHeldDate(cal.days, today, courseId);
    if (last) {
      html += esc(last.slice(0, 4)) + '年の開催は <b>' + esc(fmtDate(last)) + '</b> で終了しました。';
    }
    html += '次回の開催日程は JRA の発表後に掲載します。</p>';
    return html;
  }
  function lastHeldDate(days, today, courseId) {
    var last = '';
    for (var i = 0; i < days.length; i++) {
      var r = days[i];
      if (!r || !isKey(r.date) || r.date >= today) continue;
      if (courseId && r.courseId !== courseId) continue;
      if (r.date > last) last = r.date;
    }
    return last;
  }

  function renderCourse(slot, cal, today, courseId) {
    var rows = cal.days.filter(function (r) {
      return r && isKey(r.date) && r.courseId === courseId && r.date >= today;
    }).sort(function (a, b) { return a.date < b.date ? -1 : (a.date > b.date ? 1 : 0); }).slice(0, 3);
    var html = '<div class="kg-calendar kg-calendar--course">';
    html += '<h2 class="kg-calendar__title">' + esc(courseName(courseId)) + 'の次の開催</h2>';
    if (rows.length === 0) {
      html += renderNoUpcoming(cal, today, courseId);
    } else {
      html += '<ul class="kg-calendar__list">';
      rows.forEach(function (r) {
        html += '<li class="kg-calendar__item">' +
          '<span class="kg-calendar__date">' + esc(fmtDate(r.date)) +
          (r.date === today ? ' <span class="kg-calendar__today">本日</span>' : '') + '</span>';
        if (str(r.meeting)) html += '<span class="kg-calendar__meeting">' + esc(r.meeting) + '</span>';
        splitG1(r.g1).forEach(function (n) { html += '<span class="kg-calendar__g1">GI ' + esc(n) + '</span>'; });
        if (isTentative(r)) html += tentativeMark();
        html += '</li>';
      });
      html += '</ul>';
    }
    var g = nextG1(cal.g1, today, courseId);
    if (g) html += renderNextG1(g, cal.days, today, false);
    html += renderFooter(cal);
    html += '</div>';
    slot.innerHTML = html;
  }

  // ---- エントリポイント ----
  function render() {
    var slots = document.querySelectorAll('[data-calendar]');
    if (!slots.length) return;
    var cal = getCalendar();
    var today = todayKey();
    var rendered = 0;
    for (var i = 0; i < slots.length; i++) {
      var slot = slots[i];
      var kind = str(slot.getAttribute('data-calendar'));
      try {
        if (kind === 'weekly') {
          renderWeekly(slot, cal, today);
        } else if (kind === 'course') {
          var id = str(slot.getAttribute('data-course-id'));
          if (!id) { slot.hidden = true; continue; }
          renderCourse(slot, cal, today, id);
        } else {
          slot.hidden = true;
          continue;
        }
        slot.hidden = false;
        rendered++;
      } catch (e) {
        slot.hidden = true;
      }
    }
    // ウィジェット内に置いた <div data-cta="inline"> を cta.js に描画してもらう
    if (rendered > 0) {
      try {
        if (window.KG_CTA && typeof window.KG_CTA.render === 'function') window.KG_CTA.render();
      } catch (e) { /* CTA が描けなくてもウィジェットは残す */ }
    }
  }

  window.KG_CAL = { render: render, todayKey: todayKey, fmtDate: fmtDate, fmtDateLong: fmtDateLong };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', render);
  } else {
    render();
  }
})();
